    var INITIAL_MEMORY = 536870912;
    assert(INITIAL_MEMORY >= 5242880, `INITIAL_MEMORY should be larger than STACK_SIZE, was ${INITIAL_MEMORY}! (STACK_SIZE=5242880)`);
